def get_lr(self):
    if not self._get_lr_called_within_step:
        warnings.warn("To get the last learning rate computed by the scheduler, "
                      "please use `get_last_lr()`.", UserWarning)
    warmup_factor = _get_warmup_factor_at_iter(
        self.warmup_method, self.last_epoch, self.warmup_epochs, self.warmup_factor
    )

    if self.last_epoch <= self.warmup_epochs:
        return [base_lr * warmup_factor
                for base_lr in self.base_lrs]
    return [group['lr'] * self.gamma
            for group in self.optimizer.param_groups]

def _get_closed_form_lr(self):
    return [base_lr * self.gamma ** self.last_epoch
            for base_lr in self.base_lrs]

def get_lr(self) -> List[float]:
    if self.last_epoch <= self.warmup_epochs:
        warmup_factor = _get_warmup_factor_at_iter(
            self.warmup_method, self.last_epoch, self.warmup_epochs, self.warmup_factor,
        )
        return [
            base_lr * warmup_factor for base_lr in self.base_lrs
        ]
    elif self.last_epoch <= self.delay_iters:
        return self.base_lrs

    else:
        return [
            self.eta_min_lr + (base_lr - self.eta_min_lr) *
            (1 + math.cos(
                math.pi * (self.last_epoch - self.delay_iters) / (self.max_iters - self.delay_iters))) / 2
            for base_lr in self.base_lrs]

def init_hidden(self, batch_size):
    weight = next(self.parameters())
    return (weight.new_zeros(self.n_layers, batch_size, self.hidden_size),
            weight.new_zeros(self.n_layers, batch_size, self.hidden_size))

def forward(self, x):
    out = x
    for i in range(self.n_layers - 1):
        out = self.MLP[i](self.drop(out))
        out = self.activation_function(out)
    return self.MLP[-1](self.drop(out))

def forward(self, inputs, attn_bias=None, past_cache=None):
    if past_cache is not None:
        assert isinstance(past_cache, tuple), 'unknown type of `past_cache`, expect tuple or list. got %s' % repr(
            type(past_cache))
        past_cache = list(zip(*past_cache))
    else:
        past_cache = [None] * len(self.block)
    cache_list_k, cache_list_v, hidden_list = [], [], [inputs]

    for b, p in zip(self.block, past_cache):
        inputs, cache = b(inputs, attn_bias=attn_bias, past_cache=p)
        cache_k, cache_v = cache
        cache_list_k.append(cache_k)
        cache_list_v.append(cache_v)
        hidden_list.append(inputs)

    return inputs, hidden_list, (cache_list_k, cache_list_v)

def make_optimizer(cfg, model):
    params = []
    for key, value in model.named_parameters():
        if not value.requires_grad:
            continue
        lr = cfg.SOLVER.BASE_LR
        weight_decay = cfg.SOLVER.WEIGHT_DECAY
        if "bias" in key:
            lr = cfg.SOLVER.BASE_LR * cfg.SOLVER.BIAS_LR_FACTOR
            weight_decay = cfg.SOLVER.WEIGHT_DECAY_BIAS
        params += [{"params": [value], "lr": lr, "weight_decay": weight_decay}]
    if cfg.SOLVER.OPTIMIZER_NAME == 'SGD':
        optimizer = getattr(torch.optim, cfg.SOLVER.OPTIMIZER_NAME)(params, momentum=cfg.SOLVER.MOMENTUM)
    else:
        optimizer = getattr(torch.optim, cfg.SOLVER.OPTIMIZER_NAME)(params)
    return optimizer

