        return len(str2)
    if not str2:
        return len(str1)

    dp = [[0 for _ in range(len(str2) + 1)] for _ in range(len(str1) + 1)]

    for i in range(0, len(str1) + 1):
        dp[i][0] = i

    for j in range(0, len(str2) + 1):
        dp[0][j] = j

    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

    return dp[-1][-1]

def feed(self, char, map):
    node = map[self.pool + char]

    if node.have_child:
        if node.is_tail:
            if node.is_original:
                cond = UNMATCHED_SWITCH
            else:
                cond = MATCHED_SWITCH
        else:
            cond = CONNECTOR
    else:
        if node.is_tail:
            cond = TAIL
        else:
            cond = ERROR

    new = None
    if cond == ERROR:
        self.state = FAIL
    elif cond == TAIL:
        if self.state == WAIT_TAIL and node.is_original_long_word():
            self.state = FAIL
        else:
            self.final += node.to_word
            self.len += 1
            self.pool = UEMPTY
            self.state = END
    elif self.state == START or self.state == WAIT_TAIL:
        if cond == MATCHED_SWITCH:
            new = self.clone(node.from_word)
            self.final += node.to_word
            self.len += 1
            self.state = END
            self.pool = UEMPTY
        elif cond == UNMATCHED_SWITCH or cond == CONNECTOR:
            if self.state == START:
                new = self.clone(node.from_word)
                self.final += node.to_word
                self.len += 1
                self.state = END
            else:
                if node.is_follow(self.pool):
                    self.state = FAIL
                else:
                    self.pool = node.from_word
    elif self.state == END:
        # END is a new START
        self.state = START
        new = self.feed(char, map)
    elif self.state == FAIL:
        raise StatesMachineException('Translate States Machine '
                                     'have error with input data %s' % node)
    return new

def __init__(self, name, mapping=None):
    self.name = name
    self._map = {}
    if mapping:
        self.set_convert_map(mapping)

def set_convert_map(self, mapping):
    convert_map = {}
    have_child = {}
    max_key_length = 0
    for key in sorted(mapping.keys()):
        if len(key) > 1:
            for i in range(1, len(key)):
                parent_key = key[:i]
                have_child[parent_key] = True
        have_child[key] = False
        max_key_length = max(max_key_length, len(key))
    for key in sorted(have_child.keys()):
        convert_map[key] = (key in mapping, have_child[key],
                            mapping.get(key, UEMPTY))
    self._map = convert_map
    self.max_key_length = max_key_length

def __str__(self):
    return '<StatesMachine %s, pool: "%s", state: %s, final: %s>' % (
        id(self), self.pool, self.state, self.final)

def safe_extract(tar, path=".", members=None, *, numeric_owner=False):

    for member in tar.getmembers():
        member_path = os.path.join(path, member.name)
        if not is_within_directory(path, member_path):
            raise Exception("Attempted Path Traversal in Tar File")

    tar.extractall(path, members, numeric_owner=numeric_owner)

def feed(self, char):
    branches = []
    for fsm in self.machines:
        new = fsm.feed(char, self.map)
        if new:
            branches.append(new)
    if branches:
        self.machines.extend(branches)
    self.machines = [fsm for fsm in self.machines if fsm.state != FAIL]
    all_ok = True
    for fsm in self.machines:
        if fsm.state != END:
            all_ok = False
    if all_ok:
        self._clean()
    return self.get_result()

def _clean(self):
    if len(self.machines):
        self.machines.sort(key=lambda x: len(x))
        # self.machines.sort(cmp=lambda x,y: cmp(len(x), len(y)))
        self.final += self.machines[0].final
    self.machines = [StatesMachine()]

def convert(self, string):
    self.start()
    for char in string:
        self.feed(char)
    self.end()
    return self.get_result()

def bigrams(words, join_string, skip=0):
    """
    Input: a list of words, e.g., ["I", "am", "Denny"]
    Output: a list of bigram, e.g., ["I_am", "am_Denny"]
    """
    assert type(words) == list
    L = len(words)
    if L > 1:
        lst = []
        for i in range(L - 1):
            for k in range(1, skip + 2):
                if i + k < L:
                    lst.append(join_string.join([words[i], words[i + k]]))
    else:
        # set it as unigram
        lst = NgramUtil.unigrams(words)
    return lst

def trigrams(words, join_string, skip=0):
    """
    Input: a list of words, e.g., ["I", "am", "Denny"]
    Output: a list of trigram, e.g., ["I_am_Denny"]
    """
    assert type(words) == list
    L = len(words)
    if L > 2:
        lst = []
        for i in range(L - 2):
            for k1 in range(1, skip + 2):
                for k2 in range(1, skip + 2):
                    if i + k1 < L and i + k1 + k2 < L:
                        lst.append(join_string.join([words[i], words[i + k1], words[i + k1 + k2]]))
    else:
        # set it as bigram
        lst = NgramUtil.bigrams(words, join_string, skip)
    return lst

def ngrams(words, ngram, join_string=" "):
    """
    wrapper for ngram
    """
    ngram = int(ngram)
    if ngram == 1:
        return NgramUtil.unigrams(words)
    elif ngram == 2:
        return NgramUtil.bigrams(words, join_string)
    elif ngram == 3:
        return NgramUtil.trigrams(words, join_string)
    elif ngram == 4:
        return NgramUtil.fourgrams(words, join_string)
    elif ngram == 12:
        unigram = NgramUtil.unigrams(words)
        bigram = [x for x in NgramUtil.bigrams(words, join_string) if len(x.split(join_string)) == 2]
        return unigram + bigram
    elif ngram == 123:
        unigram = NgramUtil.unigrams(words)
        bigram = [x for x in NgramUtil.bigrams(words, join_string) if len(x.split(join_string)) == 2]
        trigram = [x for x in NgramUtil.trigrams(words, join_string) if len(x.split(join_string)) == 3]
        return unigram + bigram + trigram
    elif ngram == 1234:
        unigram = NgramUtil.unigrams(words)
        bigram = [x for x in NgramUtil.bigrams(words, join_string) if len(x.split(join_string)) == 2]
        trigram = [x for x in NgramUtil.trigrams(words, join_string) if len(x.split(join_string)) == 3]
        fourgram = [x for x in NgramUtil.fourgrams(words, join_string) if len(x.split(join_string)) == 4]
        return unigram + bigram + trigram + fourgram

def biterms(words, join_string):
    """
    Input: a list of words, e.g., ["I", "am", "Denny", "boy"]
    Output: a list of biterm, e.g., ["I_am", "I_Denny", "I_boy", "am_Denny", "am_boy", "Denny_boy"]
    """
    assert type(words) == list
    L = len(words)
    if L > 1:
        lst = []
        for i in range(L - 1):
            for j in range(i + 1, L):
                lst.append(join_string.join([words[i], words[j]]))
    else:
        # set it as uniterm
        lst = NgramUtil.uniterms(words)
    return lst

def triterms(words, join_string):
    """
    Input: a list of words, e.g., ["I", "am", "Denny", "boy"]
    Output: a list of triterm, e.g., ["I_am_Denny", "I_am_boy", "I_Denny_boy", "am_Denny_boy"]
    """
    assert type(words) == list
    L = len(words)
    if L > 2:
        lst = []
        for i in range(L - 2):
            for j in range(i + 1, L - 1):
                for k in range(j + 1, L):
                    lst.append(join_string.join([words[i], words[j], words[k]]))
    else:
        # set it as biterm
        lst = NgramUtil.biterms(words, join_string)
    return lst

def fourterms(words, join_string):
    """
    Input: a list of words, e.g., ["I", "am", "Denny", "boy", "ha"]
    Output: a list of fourterm, e.g., ["I_am_Denny_boy", "I_am_Denny_ha", "I_am_boy_ha", "I_Denny_boy_ha", "am_Denny_boy_ha"]
    """
    assert type(words) == list
    L = len(words)
    if L > 3:
        lst = []
        for i in range(L - 3):
            for j in range(i + 1, L - 2):
                for k in range(j + 1, L - 1):
                    for l in range(k + 1, L):
                        lst.append(join_string.join([words[i], words[j], words[k], words[l]]))
    else:
        # set it as triterm
        lst = NgramUtil.triterms(words, join_string)
    return lst

def nterms(words, nterm, join_string=" "):
    """wrapper for nterm"""
    if nterm == 1:
        return NgramUtil.uniterms(words)
    elif nterm == 2:
        return NgramUtil.biterms(words, join_string)
    elif nterm == 3:
        return NgramUtil.triterms(words, join_string)
    elif nterm == 4:
        return NgramUtil.fourterms(words, join_string)

