def run_inference(self, input_tokens, target, target_pos, k=10):
    context_vector = self.forward(input_tokens, target=None, target_pos=target_pos)
    if target is None:
        topv, topi = ((self.criterion.W.weight * context_vector).sum(dim=1)).data.topk(k)
        return topv, topi
    else:
        context_vector /= torch.norm(context_vector, p=2)
        target_vector = self.criterion.W.weight[target]
        target_vector /= torch.norm(target_vector, p=2)
        similarity = (target_vector * context_vector).sum()
        return similarity.item()

def negative_sampling(self, shape):
    if self.n_negatives > 0:
        return torch.tensor(self.sampler.sample(shape=shape), dtype=torch.long, device=self.device)
    else:
        raise NotImplementedError

def truncate(self, id1, id2, seqlen):
    len1 = len(id1)
    len2 = len(id2)
    half = seqlen // 2
    if len1 > len2:
        len1_truncated, len2_truncated = max(half, seqlen - len2), min(half, len2)
    else:
        len1_truncated, len2_truncated = min(half, seqlen - len1), max(half, seqlen - len1)
    return id1[: len1_truncated], id2[: len2_truncated]

def encode(self, text, pair=None, truncate_to=None):
    text_id = np.array(self.convert_tokens_to_ids(self.tokenize(text)), dtype=np.int64)
    if pair is not None:
        pair_id = np.array(self.convert_tokens_to_ids(self.tokenize(pair)), dtype=np.int64)
    else:
        pair_id = []
    if truncate_to is not None:
        text_id, pair_id = self.truncate(text_id, [] if pair_id is None else pair_id, truncate_to)

    ret_id, ret_id_type = self.build_for_ernie(text_id, pair_id)
    return ret_id, ret_id_type

